// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { ArrayLike } from '@stdlib/types/array';
import { typedndarray } from '@stdlib/types/ndarray';

/**
* Callback invoked for each element in an ndarray.
*/
type Nullary<ThisArg> = ( this: ThisArg ) => void;

/**
* Callback invoked for each element in an ndarray.
*
* @param value - current array element
*/
type Unary<T, ThisArg> = ( this: ThisArg, value: T ) => void;

/**
* Callback invoked for each element in an ndarray.
*
* @param value - current array element
* @param indices - current array element indices
*/
type Binary<T, ThisArg> = ( this: ThisArg, value: T, indices: Array<number> ) => void;

/**
* Callback invoked for each element in an ndarray.
*
* @param value - current array element
* @param indices - current array element indices
* @param arr - input array
*/
type Ternary<T, U, ThisArg> = ( this: ThisArg, value: T, indices: Array<number>, arr: U ) => void;

/**
* Callback invoked for each element in an ndarray.
*
* @param value - current array element
* @param indices - current array element indices
* @param arr - input array
*/
type Callback<T, U, ThisArg> = Nullary<ThisArg> | Unary<T, ThisArg> | Binary<T, ThisArg> | Ternary<T, U, ThisArg>;

/**
* Predicate function invoked for each element in an ndarray.
*/
type NullaryPredicate = () => boolean;

/**
* Predicate function invoked for each element in an ndarray.
*
* @param value - current array element
*/
type UnaryPredicate<T> = ( value: T ) => boolean;

/**
* Predicate function invoked for each element in an ndarray.
*
* @param value - current array element
* @param indices - current array element indices
*/
type BinaryPredicate<T> = ( value: T, indices: Array<number> ) => boolean;

/**
* Predicate function invoked for each element in an ndarray.
*
* @param value - current array element
* @param indices - current array element indices
* @param arr - input array
*/
type TernaryPredicate<T, U> = ( value: T, indices: Array<number>, arr: U ) => boolean;

/**
* Predicate function invoked for each element in an ndarray.
*
* @param value - current array element
* @param indices - current array element indices
* @param arr - input array
*/
type Predicate<T, U> = NullaryPredicate | UnaryPredicate<T> | BinaryPredicate<T> | TernaryPredicate<T, U>;

/**
* While a test condition is true, invokes a callback function for each element in an ndarray.
*
* @param arrays - array-like object containing an input ndarray
* @param predicate - predicate function
* @param fcn - callback function
* @param thisArg - callback function execution context
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var naryFunction = require( '@stdlib/utils/nary-function' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
* var log = require( '@stdlib/console/log' );
*
* function predicate( value ) {
*     return value === value;
* }
*
* // Create a data buffer:
* var xbuf = new Float64Array( 12 );
*
* // Define the shape of the array:
* var shape = [ 3, 1, 2 ];
*
* // Define the array strides:
* var sx = [ 4, 4, 1 ];
*
* // Define the index offset:
* var ox = 1;
*
* // Create the input ndarray:
* var x = ndarray( 'float64', xbuf, shape, sx, ox, 'row-major' );
*
* // Apply the callback function:
* whileEach( [ x ], predicate, naryFunction( log, 1 ) );
*/
declare function whileEach<T = unknown, U extends typedndarray<T> = typedndarray<T>, ThisArg = unknown>( arrays: ArrayLike<U>, predicate: Predicate<T, U>, fcn: Callback<T, U, ThisArg>, thisArg?: ThisParameterType<Callback<T, U, ThisArg>> ): void;


// EXPORTS //

export = whileEach;
